CREATE TABLE routes (id BIGINT PRIMARY KEY AUTO_INCREMENT, origin VARCHAR(80) NOT NULL, destination VARCHAR(80) NOT NULL, UNIQUE KEY uq_route (origin,destination));
CREATE TABLE buses (id BIGINT PRIMARY KEY AUTO_INCREMENT, operator_name VARCHAR(120) NOT NULL, bus_number VARCHAR(30) NOT NULL UNIQUE, bus_type VARCHAR(80) NOT NULL, amenities VARCHAR(255) NOT NULL DEFAULT '');
CREATE TABLE trips (id BIGINT PRIMARY KEY AUTO_INCREMENT, route_id BIGINT NOT NULL, bus_id BIGINT NOT NULL, departure_at DATETIME NOT NULL, arrival_at DATETIME NOT NULL, fare DECIMAL(10,2) NOT NULL, FOREIGN KEY(route_id) REFERENCES routes(id), FOREIGN KEY(bus_id) REFERENCES buses(id), INDEX ix_trip_departure(departure_at));
CREATE TABLE trip_seats (id BIGINT PRIMARY KEY AUTO_INCREMENT, trip_id BIGINT NOT NULL, seat_code VARCHAR(8) NOT NULL, seat_type VARCHAR(20) NOT NULL DEFAULT 'SEATER', status VARCHAR(16) NOT NULL DEFAULT 'AVAILABLE', UNIQUE KEY uq_trip_seat(trip_id,seat_code), FOREIGN KEY(trip_id) REFERENCES trips(id));
CREATE TABLE bookings (id BIGINT PRIMARY KEY AUTO_INCREMENT, pnr VARCHAR(20) NOT NULL UNIQUE, trip_id BIGINT NOT NULL, passenger_name VARCHAR(120) NOT NULL, phone VARCHAR(20) NOT NULL, email VARCHAR(180) NOT NULL, seat_codes VARCHAR(200) NOT NULL, amount DECIMAL(10,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'CONFIRMED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(trip_id) REFERENCES trips(id));
